import{Et as e,Ot as t,n,qt as r}from"./chunks/framework.B_qehzBO.js";var i=JSON.parse(`{"title":"TextSense — Microservicio NLP","description":"Microservicio de análisis de sentimiento con backend transformer y fallback léxico determinista: inferencia por lotes, caché, métricas Prometheus, pruebas offline.","frontmatter":{"title":"TextSense — Microservicio NLP","description":"Microservicio de análisis de sentimiento con backend transformer y fallback léxico determinista: inferencia por lotes, caché, métricas Prometheus, pruebas offline."},"headers":[],"relativePath":"es/projects/textsense/index.md","filePath":"es/projects/textsense/index.md"}`),a={name:`es/projects/textsense/index.md`};function o(n,i,a,o,s,c){return r(),e(`div`,null,[...i[0]||=[t(`<h1 id="textsense-—-microservicio-nlp" tabindex="-1">TextSense — Microservicio NLP <a class="header-anchor" href="#textsense-—-microservicio-nlp" aria-label="Permalink to “TextSense — Microservicio NLP”">​</a></h1><p><strong><a href="https://github.com/Godde3s/textsense" target="_blank" rel="noreferrer">TextSense</a></strong> es como se ve un servicio de ML cuando lo construye un ingeniero de backend: el modelo es la parte fácil; todo lo demás — health probes, métricas, degradación elegante, endurecimiento de payloads — es la ingeniería real.</p><h2 id="el-fallback-es-la-funcionalidad" tabindex="-1">El fallback es la funcionalidad <a class="header-anchor" href="#el-fallback-es-la-funcionalidad" aria-label="Permalink to “El fallback es la funcionalidad”">​</a></h2><p>La mayoría de las &quot;APIs&quot; de NLP mueren el día que falla la descarga del modelo. TextSense envuelve la inferencia en un <strong>patrón estrategia</strong>: intenta el backend <code>transformers</code> (DistilBERT SST-2 en CPU) y, si torch no está disponible o la inferencia falla, degrada a un <strong>motor léxico determinista</strong> en stdlib puro. El contrato HTTP nunca cambia — cada respuesta lleva un <code>model</code> id (<code>distilbert-sst2</code> o <code>lexicon-v1</code>).</p><p>El motor léxico es genuinamente útil: manejo de negaciones, intensificadores y énfasis — lo bastante determinista para que toda la suite corra <strong>offline en menos de un segundo</strong>, sin descargas gigantes ni GPU.</p><h2 id="lo-que-el-servicio-entrega" tabindex="-1">Lo que el servicio entrega <a class="header-anchor" href="#lo-que-el-servicio-entrega" aria-label="Permalink to “Lo que el servicio entrega”">​</a></h2><ul><li><code>POST /api/v1/sentiment</code> — texto → etiqueta, confianza, latencia, request id</li><li><code>POST /api/v1/sentiment/batch</code> — hasta 64 textos, orden preservado, caché</li><li><code>GET /metrics</code> — formato Prometheus: contadores, latencia, aciertos de caché</li><li><code>GET /health</code> — backend id + uptime para orquestadores</li><li>Auth opcional <code>X-API-Key</code>, límites de payload con <code>413</code> honestos</li></ul><div class="tip custom-block"><p class="custom-block-title">Pruébalo</p><p><code>docker compose up --build</code>, y envía una frase a <code>/api/v1/sentiment</code> — <a href="https://github.com/Godde3s/textsense" target="_blank" rel="noreferrer">github.com/Godde3s/textsense</a></p></div>`,8)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};